import os,errno,stat
def restore_sparse(source,target):
    source_fd=os.open(source,os.O_RDONLY|os.O_NOFOLLOW)
    target_fd=None;created=False
    try:
        info=os.fstat(source_fd)
        if not stat.S_ISREG(info.st_mode):raise ValueError('regular source required')
        target_fd=os.open(target,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600);created=True
        offset=0
        while offset<info.st_size:
            try:data=os.lseek(source_fd,offset,os.SEEK_DATA)
            except OSError as error:
                if error.errno==errno.ENXIO:break
                raise
            end=min(os.lseek(source_fd,data,os.SEEK_HOLE),info.st_size)
            if end<=data:raise OSError('invalid native extent')
            position=data
            while position<end:
                block=os.pread(source_fd,min(65536,end-position),position)
                if not block:raise OSError('source shortened during restore')
                written=0
                while written<len(block):
                    count=os.pwrite(target_fd,block[written:],position+written)
                    if count<=0:raise OSError('zero progress write')
                    written+=count
                position+=len(block)
            offset=end
        os.ftruncate(target_fd,info.st_size)
        os.fchmod(target_fd,stat.S_IMODE(info.st_mode))
        os.fsync(target_fd)
        after=os.fstat(source_fd)
        if (after.st_size,after.st_mtime_ns,after.st_ctime_ns)!=(info.st_size,info.st_mtime_ns,info.st_ctime_ns):raise OSError('source changed')
    except BaseException:
        if created:os.unlink(target)
        raise
    finally:
        if target_fd is not None:os.close(target_fd)
        os.close(source_fd)
```

原题说明：
交付虚拟磁盘格式、稀疏区段、虚机停写或检查点协议与恢复步骤。文件逻辑大小可能远大于物理占用，备份工具需明确是否保留稀疏及增量分配语义；复制正在运行的磁盘还可能产生时间上不一致的数据，需使用虚拟化平台支持的备份能力。验收恢复文件摘要或格式校验、实际占用及来宾启动和业务检查，不能只比较文件长度。目标空间不足则中止并保留旧副本，禁止把半份恢复文件作为可启动卷。切回旧卷前处理新卷已产生的写入，避免默默丢弃恢复验证期间数据。

