import os,time
def write_throughput(path,chunks):
    if not isinstance(chunks,list) or not chunks or any(type(x) is not bytes or not x for x in chunks):raise ValueError('nonempty bytes chunks required')
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    try:
        total=0;started=time.monotonic_ns()
        for chunk in chunks:
            offset=0
            while offset<len(chunk):
                count=os.write(fd,chunk[offset:])
                if count<=0:raise OSError('zero-progress write')
                offset+=count;total+=count
        os.fsync(fd)
        elapsed=time.monotonic_ns()-started
        if elapsed<=0:raise RuntimeError('clock did not advance')
        seconds=elapsed/1_000_000_000
        return {'bytes':total,'seconds':seconds,'bytes_per_second':total/seconds,'MiB_per_second':total/seconds/(1024*1024)}
    except BaseException:
        os.unlink(path)
        raise
    finally:os.close(fd)
```

